import{_ as n,a0 as d,w as p,s as o,I as i,x as s,a1 as t,A as l,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何使用 Buildah 構建容器鏡像 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Buildah 構建容器鏡像 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Buildah 構建容器鏡像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Buildah 構建容器鏡像 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180503 How to build container images with Buildah","title":"如何使用 Buildah 構建容器鏡像","tag":"201805","desc":""},"relativePath":"201805/20180503 How to build container images with Buildah.md","filePath":"[post].md"}'),r={name:"201805/20180503 How to build container images with Buildah.md"};function g(u,a,b,k,c,f){const e=d("Link");return p(),o("div",null,[a[21]||(a[21]=i("h1",{id:"如何使用-buildah-構建容器鏡像",tabindex:"-1"},[s("如何使用 Buildah 構建容器鏡像 "),i("a",{class:"header-anchor",href:"#如何使用-buildah-構建容器鏡像","aria-label":"Permalink to “如何使用 Buildah 構建容器鏡像”"},"​")],-1)),a[22]||(a[22]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/04/buildah-816x345.png",alt:""})],-1)),i("p",null,[a[1]||(a[1]=s("Project Atomic 通過他們在 Open Container Initiative（OCI）上的努力創造了一個名為 ",-1)),t(e,{href:"https://github.com/projectatomic/buildah"},{default:l(()=>[...a[0]||(a[0]=[s("Buildah",-1)])]),_:1}),a[2]||(a[2]=s(" 的偉大工具。Buildah 能幫助創建、構建和更新，它支持 Docker 容器鏡像以及 OCI 兼容鏡像。",-1))]),a[23]||(a[23]=h(`<p>Buildah 處理構建容器鏡像時無需安裝完整的容器運行時或守護進程。這對建立容器的持續集成和持續交付管道尤其有用。</p><p>Buildah 使容器的文件系統可以直接供構建主機使用。這意味着構建工具在主機上可用就行，而不需要在容器鏡像中可用，從而使構建更快速，鏡像更小，更安全。Buildah 有 CentOS、Fedora 和 Debian 的軟件包。</p><h3 id="安裝-buildah" tabindex="-1">安裝 Buildah <a class="header-anchor" href="#安裝-buildah" aria-label="Permalink to “安裝 Buildah”">​</a></h3><p>從 Fedora 26 開始 Buildah 可以使用 <code>dnf</code> 進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install buildah -y</span></span></code></pre></div><p><code>buildah</code> 的當前版本為 0.16，可以通過以下命令顯示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ buildah --version</span></span></code></pre></div><h3 id="基本命令" tabindex="-1">基本命令 <a class="header-anchor" href="#基本命令" aria-label="Permalink to “基本命令”">​</a></h3><p>構建容器鏡像的第一步是獲取基礎鏡像，這是通過 Dockerfile 中的 <code>FROM</code> 語句完成的。Buildah 以類似的方式處理這個。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from fedora</span></span></code></pre></div><p>該命令將拉取 Fedora 的基礎鏡像並存儲在主機上。通過執行以下操作可以檢查主機上可用的鏡像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah images</span></span>
<span class="line"><span>IMAGE ID IMAGE NAME CREATED AT SIZE</span></span>
<span class="line"><span>9110ae7f579f docker.io/library/fedora:latest Mar 7, 2018 20:51 234.7 MB</span></span></code></pre></div><p>在拉取基礎鏡像後，有一個該鏡像的運行容器實例，這是一個“工作容器”。</p><p>以下命令顯示正在運行的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah containers</span></span>
<span class="line"><span>CONTAINER ID BUILDER IMAGE ID IMAGE NAME</span></span>
<span class="line"><span>CONTAINER NAME</span></span>
<span class="line"><span>6112db586ab9 * 9110ae7f579f docker.io/library/fedora:latest fedora-working-container</span></span></code></pre></div><p>Buildah 還提供了一個非常有用的命令來停止和刪除當前正在運行的所有容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah rm --all</span></span></code></pre></div><p>完整的命令列表可以使用 <code>--help</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ buildah --help</span></span></code></pre></div><h3 id="構建一個-apache-web-服務器容器鏡像" tabindex="-1">構建一個 Apache Web 服務器容器鏡像 <a class="header-anchor" href="#構建一個-apache-web-服務器容器鏡像" aria-label="Permalink to “構建一個 Apache Web 服務器容器鏡像”">​</a></h3><p>讓我們看看如何使用 Buildah 在 Fedora 基礎鏡像上安裝 Apache Web 服務器，然後複製一個可供服務的自定義 <code>index.html</code>。</p><p>首先讓我們創建自定義的 <code>index.html</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Hello Fedora Magazine !!!&quot; &gt; index.html</span></span></code></pre></div><p>然後在正在運行的容器中安裝 httpd 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from fedora</span></span>
<span class="line"><span>$ sudo buildah run fedora-working-container dnf install httpd -y</span></span></code></pre></div><p>讓我們將 <code>index.html</code> 複製到 <code>/var/www/html/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah copy fedora-working-container index.html /var/www/html/index.html</span></span></code></pre></div><p>然後配置容器入口點以啓動 httpd。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah config --entrypoint &quot;/usr/sbin/httpd -DFOREGROUND&quot; fedora-working-container</span></span></code></pre></div><p>現在為了使“工作容器”可用，<code>commit</code> 命令將容器保存到鏡像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah commit fedora-working-container hello-fedora-magazine</span></span></code></pre></div><p>hello-fedora-magazine 鏡像現在可用，並且可以推送到倉庫以供使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah images</span></span>
<span class="line"><span>IMAGE ID IMAGE NAME CREATED</span></span>
<span class="line"><span>AT SIZE</span></span>
<span class="line"><span>9110ae7f579f docker.io/library/fedora:latest</span></span>
<span class="line"><span>Mar 7, 2018 22:51 234.7 MB</span></span>
<span class="line"><span>49bd5ec5be71 docker.io/library/hello-fedora-magazine:latest</span></span>
<span class="line"><span>Apr 27, 2018 11:01 427.7 MB</span></span></code></pre></div><p>通過運行以下步驟，還可以使用 Buildah 來測試此鏡像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from --name=hello-magazine docker.io/library/hello-fedora-magazine</span></span>
<span class="line"><span>$ sudo buildah run hello-magazine</span></span></code></pre></div>`,35)),i("p",null,[a[4]||(a[4]=s("訪問 ",-1)),t(e,{href:"http://localhost"},{default:l(()=>[...a[3]||(a[3]=[s("http://localhost",-1)])]),_:1}),a[5]||(a[5]=s(" 將顯示 “Hello Fedora Magazine !!!”",-1))]),a[24]||(a[24]=i("hr",null,null,-1)),i("p",null,[a[7]||(a[7]=s("via: ",-1)),t(e,{href:"https://fedoramagazine.org/daemon-less-container-management-buildah/"},{default:l(()=>[...a[6]||(a[6]=[s("https://fedoramagazine.org/daemon-less-container-management-buildah/",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("作者：",-1)),t(e,{href:"https://fedoramagazine.org/author/ashutoshbhakare/"},{default:l(()=>[...a[8]||(a[8]=[s("Ashutosh Sudhakar Bhakare",-1)])]),_:1}),a[13]||(a[13]=s(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:l(()=>[...a[10]||(a[10]=[s("geekpi",-1)])]),_:1}),a[15]||(a[15]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[18]||(a[18]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...a[17]||(a[17]=[s("Linux中國",-1)])]),_:1}),a[20]||(a[20]=s(" 榮譽推出",-1))])])}const x=n(r,[["render",g]]);export{C as __pageData,x as default};
